define('ui/resourcemgr/filePreview',['jquery', 'lodash', 'util/bytes', 'context', 'ui/previewer'], function ($, _, bytes, context, previewer) {
  'use strict';

  $ = $ && Object.prototype.hasOwnProperty.call($, 'default') ? $['default'] : $;
  _ = _ && Object.prototype.hasOwnProperty.call(_, 'default') ? _['default'] : _;
  bytes = bytes && Object.prototype.hasOwnProperty.call(bytes, 'default') ? bytes['default'] : bytes;
  context = context && Object.prototype.hasOwnProperty.call(context, 'default') ? context['default'] : context;
  var ns = 'resourcemgr';
  var EMPTY_META = '-';
  function filePreview(options) {
    var $container = options.$target;
    var $filePreview = $('.file-preview', $container);
    var $previewer = $('.previewer', $container);
    var $propType = $('.prop-type', $filePreview);
    var $propSize = $('.prop-size', $filePreview);
    var $propUrl = $('.prop-url', $filePreview);
    var $link = $('a', $propUrl);
    var $selectButton = $('.select-action', $filePreview);
    var currentSelection = [];
    $container.on("fileselect.".concat(ns), function (e, file) {
      var $listItem = $container[0].querySelector("[data-file='".concat(file.file, "']"));
      if (file && file.file && $listItem && $listItem.dataset) {
        startPreview(file, $listItem.dataset.preview === 'true', $listItem.dataset.download === 'true', $listItem.dataset.select === 'true');
        currentSelection = file;
      } else {
        stopPreview();
      }
    });
    $container.on("filedelete.".concat(ns), function (e, path) {
      if (currentSelection.file === path) {
        stopPreview();
      }
    });
    $selectButton.on('click', function (e) {
      e.preventDefault();
      var data = _.pick(currentSelection, ['file', 'type', 'mime', 'size', 'alt']);
      if (context.mediaSources && context.mediaSources.length === 0 && data.file.indexOf('local/') > -1) {
        data.file = data.file.substring(6);
      }
      $container.trigger("select.".concat(ns), [[data]]);
    });
    function metaOrDash(value) {
      if (value === null || typeof value === 'undefined' || value === '') {
        return EMPTY_META;
      }
      return String(value);
    }
    function downloadHref(file) {
      if (typeof file.downloadUrl === 'string' && file.downloadUrl) {
        return file.downloadUrl;
      }
      if (typeof file.url === 'string' && file.url) {
        var query = file.url.split('#')[0].split('?')[1] || '';
        var hasSvgzSupport = query.split('&').some(param => param.split('=')[0] === 'svgzsupport');
        return hasSvgzSupport ? file.url : "".concat(file.url, "&svgzsupport=true");
      }
      if (typeof file.download === 'string' && file.download) {
        return file.download;
      }
      return '';
    }
    function downloadFilename(file) {
      if (typeof file.display === 'string' && file.display) {
        return file.display;
      }
      var path = file.file || '';
      var idx = path.lastIndexOf('/');
      return idx >= 0 ? path.slice(idx + 1) : path;
    }
    function startPreview(file, preview, download, select) {
      if (preview) {
        $previewer.previewer(file);
        if (file.type || file.mime) {
          $propType.text(file.type && file.mime ? "".concat(file.type, " (").concat(file.mime, ")") : metaOrDash(file.type || file.mime));
        } else {
          $propType.text(EMPTY_META);
        }
        $propSize.text(file.size === null || typeof file.size === 'undefined' || file.size === '' ? EMPTY_META : bytes.hrSize(file.size));
      } else {
        $propType.text(EMPTY_META);
        $propSize.text(EMPTY_META);
      }
      if (download) {
        var href = downloadHref(file);
        if (href) {
          $link.attr('href', href).attr('download', downloadFilename(file));
          if ($link.hasClass('hidden')) {
            $link.removeClass('hidden');
          }
        } else {
          $link.attr('href', '#').removeAttr('download');
          $link.addClass('hidden');
        }
      } else {
        $link.attr('href', '#').attr('download', '#');
        $link.addClass('hidden');
      }
      if (select) {
        $selectButton.removeAttr('disabled');
      }
    }
    function stopPreview() {
      $previewer.previewer('update', {
        url: false
      });
      $propType.text(EMPTY_META);
      $propSize.text(EMPTY_META);
      $('a', $propUrl).addClass('hidden');
      $selectButton.attr('disabled', 'disabled');
    }
  }
  return filePreview;
});
